CREATE TABLE IF NOT EXISTS junctions (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(140) NOT NULL, latitude DOUBLE NOT NULL, longitude DOUBLE NOT NULL, approaches INT NOT NULL DEFAULT 4, active BOOLEAN NOT NULL DEFAULT TRUE, density_score DOUBLE NOT NULL DEFAULT 0, vehicle_count INT NOT NULL DEFAULT 0, avg_wait_seconds DOUBLE NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS signals (id BIGINT PRIMARY KEY AUTO_INCREMENT, junction_id BIGINT NOT NULL, direction VARCHAR(24) NOT NULL, state VARCHAR(16) NOT NULL DEFAULT 'RED', green_seconds INT NOT NULL DEFAULT 30, red_seconds INT NOT NULL DEFAULT 90, priority BOOLEAN NOT NULL DEFAULT FALSE, FOREIGN KEY (junction_id) REFERENCES junctions(id));
CREATE TABLE IF NOT EXISTS traffic_records (id BIGINT PRIMARY KEY AUTO_INCREMENT, junction_id BIGINT NOT NULL, vehicle_count INT NOT NULL, queue_length_m DOUBLE NOT NULL, avg_wait_seconds DOUBLE NOT NULL, density_score DOUBLE NOT NULL, density_level VARCHAR(16) NOT NULL, source VARCHAR(24) NOT NULL DEFAULT 'SIMULATION', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (junction_id) REFERENCES junctions(id));
CREATE TABLE IF NOT EXISTS incidents (id BIGINT PRIMARY KEY AUTO_INCREMENT, type VARCHAR(60) NOT NULL, latitude DOUBLE NOT NULL, longitude DOUBLE NOT NULL, description TEXT, severity VARCHAR(20) NOT NULL DEFAULT 'MEDIUM', status VARCHAR(20) NOT NULL DEFAULT 'OPEN', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS emergency_events (id BIGINT PRIMARY KEY AUTO_INCREMENT, vehicle_type VARCHAR(32) NOT NULL, origin_lat DOUBLE NOT NULL, origin_lng DOUBLE NOT NULL, destination_lat DOUBLE NOT NULL, destination_lng DOUBLE NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'REPORTED', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS video_analyses (id BIGINT PRIMARY KEY AUTO_INCREMENT, junction_id BIGINT NOT NULL, total_vehicles INT NOT NULL DEFAULT 0, peak_visible_vehicles INT NOT NULL DEFAULT 0, density_score DOUBLE NOT NULL DEFAULT 0, density_level VARCHAR(16) NOT NULL, analysis_json LONGTEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_video_analysis_junction_created (junction_id, created_at), FOREIGN KEY (junction_id) REFERENCES junctions(id));
INSERT INTO junctions(name,latitude,longitude,approaches) SELECT 'Central Square',12.9716,77.5946,4 WHERE NOT EXISTS (SELECT 1 FROM junctions);
INSERT INTO junctions(name,latitude,longitude,approaches) SELECT 'Market Road',12.9750,77.6010,4 WHERE (SELECT COUNT(*) FROM junctions)=1;
INSERT INTO junctions(name,latitude,longitude,approaches) SELECT 'City Hospital Junction',12.9660,77.5850,4 WHERE (SELECT COUNT(*) FROM junctions)=2;
INSERT INTO signals(junction_id,direction) SELECT j.id,d.direction FROM junctions j CROSS JOIN (SELECT 'NORTH' direction UNION SELECT 'SOUTH' UNION SELECT 'EAST' UNION SELECT 'WEST') d WHERE NOT EXISTS (SELECT 1 FROM signals s WHERE s.junction_id=j.id AND s.direction=d.direction);
